local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
local MaxCount = 3
local HorizontalLayoutGroup = CS.UnityEngine.UI.HorizontalLayoutGroup
local backpackComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BackpackComponent)

---@class UICatHouseBlindboxPopupDialog
---@field IconList                      	SuperScrollView.LoopListView2
---@field Root                          	UnityEngine.RectTransform
local UICatHouseBlindboxPopupDialog = Class("UICatHouseBlindboxPopupDialog")

function UICatHouseBlindboxPopupDialog:__init() 
    self._blindBoxlist = {}          --盲盒
end

function UICatHouseBlindboxPopupDialog:__delete()
    self._blindBoxlist = nil          --盲盒
end

function UICatHouseBlindboxPopupDialog:Awake()
    SetButtonAction(self.controller.gameObject, function()
        UIModule.CloseDialog(self.controller)
    end)

    local closeBtn = self.Root.transform:Find("Details/BtnClose")
    if closeBtn then
        SetButtonAction(closeBtn.gameObject, function()
            UIModule.CloseDialog(self.controller)
        end)
    end
    self:InitData()
    self:FillSelf()
end

function UICatHouseBlindboxPopupDialog:InitData()
    self._blindBoxlist = {}
    local t = backpackComponent:GetBlindBoxData()
    if t then
        local count = 1
        local _t = {}
        for k, v in pairs(t) do
            if table.count(_t) >= MaxCount then
                table.insert(self._blindBoxlist, _t)
                _t = {}
            end
            table.insert(_t, v)
        end
        if table.count(_t) >= 1 then
            table.insert(self._blindBoxlist, _t)
        end
    end
end

function UICatHouseBlindboxPopupDialog:FillSelf()
    if self._isInitList then
        GameUtils.ReloadData(self.IconList, table.count(self._blindBoxlist))
    else
        self.IconList:InitListView(table.count(self._blindBoxlist), Bind(self, self.OnGetCellIndex))
        self._isInitList = true
    end
end

function UICatHouseBlindboxPopupDialog:OnGetCellIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("ItemPrefab")
    local data = self._blindBoxlist[index + 1]
    self:FillListCell(cell.gameObject, data)

    return cell    
end

function UICatHouseBlindboxPopupDialog:FillListCell(go, data)
    if not go or not data then
        return
    end
    local horizontalLayoutGroup = go.transform:Find("Layout"):GetComponent(typeof(HorizontalLayoutGroup))
    if table.count(self._blindBoxlist) > 1 then
        horizontalLayoutGroup.childAlignment = CS.UnityEngine.TextAnchor.MiddleLeft
    else
        horizontalLayoutGroup.childAlignment = CS.UnityEngine.TextAnchor.MiddleCenter
    end

    for k, v in pairs(data) do
        local goodsGo = go.transform:Find("Layout/GoodNode"..k)
        if goodsGo then
            CfUtils.RefeshGoodGo(goodsGo, v.goodsId, string.format("X%s",v.num), Vector3(0.9, 0.9, 0.9), nil, function()
                local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
                local dojo = comp:GetCatHouseHomeDojo()
                if not dojo then
                    return
                end
                
                local catHouseCatNum = CatHouseMgr:GetInstance():GetCatNum()
                if catHouseCatNum >= checkNumber(dojo.maxCatsNum) then
                    GameUtils.Toast(localize("猫猫已达到最大数量"))
                    return
                end

                GameUtils.Request(Interfaces.BackpackOpen, { goodsId = v.goodsId, num = 1 }, function(request, response)
                    if checkNumber(response.errCode) ~= 0 then
                        return
                    end
                    local data = response.data
                    comp:AddCatData(data.cat)
                    for k, v in pairs(data.cat.genes) do
                        comp:AddUnlockedGene(v.geneId)
                    end

                    GoodsUtils.DrawRewards({{
                        goodsId = v.goodsId,
                        num = -1
                    }})

                    local t = backpackComponent:GetBlindBoxData()
                    if table.count(t) <= 0 then
                        UIModule.CloseDialog(self.controller)
                    else
                        self:InitData()
                        self:FillSelf()
                    end

                    UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationGetCatPopup, parameters = {viewType = 2, playerCatId = data.cat.id, blindBoxId = v.goodsId}})
                end)
            end)
            KTool.SetActive(goodsGo, true)
        end
    end

    if table.count(data) < MaxCount then
        for i = table.count(data) + 1, MaxCount do
            local goodsGo = go.transform:Find("Layout/GoodNode"..i)
            if goodsGo then
                KTool.SetActive(goodsGo, false)
            end
        end
    end
end


function UICatHouseBlindboxPopupDialog:OnFocus(focus)
    KTool.SetActive(self.controller.gameObject, checkBool(focus))
end

